public readonly record struct AppearanceTemplate(ushort Id, byte Race, bool Female,
    ushort Skin, ushort Hair, ushort HairHue, ushort Beard, ushort BeardHue)
{
    public int Group => (Id - 1) / AppearanceTemplates.PerGroup;
    public int Index => (Id - 1) % AppearanceTemplates.PerGroup;
}

