    public static ushort IdAt(byte race, bool female, int index)
    {
        if (race is < 1 or > 3 || index is < 0 or >= PerGroup)
            throw new ArgumentOutOfRangeException(nameof(index));
        return (ushort)(1 + ((race - 1) * 2 + (female ? 1 : 0)) * PerGroup + index);
    }

    public static bool TryGet(ushort id, out AppearanceTemplate template)
    {
        int offset = id - 1;
        if (offset < 0 || offset >= _looks.Length)
        {
            template = default;
            return false;
        }

        int group = offset / PerGroup;
        var look = _looks[offset];
        template = new(id, (byte)(group / 2 + 1), group % 2 != 0,
            look.Skin, look.Hair, look.HairHue, look.Beard, look.BeardHue);
        return true;
    }
